// Repro: pwm_gen output period must be PERIOD clock cycles.
module pwm_repro_tb;
    localparam integer PERIOD = 8;

    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer cyc, last_rise, n_rises, prev;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;

        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (3*PERIOD) @(negedge clk);

        prev = pwm;
        last_rise = -1;
        n_rises = 0;
        for (cyc = 0; (cyc < 6*PERIOD) && (n_rises < 4); cyc = cyc + 1) begin
            @(negedge clk);
            if (prev == 0 && pwm == 1'b1) begin
                if (last_rise >= 0) begin
                    if (cyc - last_rise == PERIOD) begin
                        passed = passed + 1;
                    end else begin
                        failed = failed + 1;
                        $display("FAIL period: %0d cycles between rising edges, expected %0d",
                                 cyc - last_rise, PERIOD);
                    end
                end
                last_rise = cyc;
                n_rises = n_rises + 1;
            end
            prev = pwm;
        end
        if (n_rises < 4) begin
            failed = failed + 1;
            $display("FAIL period: only %0d rising edges seen in %0d cycles", n_rises, 6*PERIOD);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
