`timescale 1ns / 1ps
// Repro: a change of `duty` in the middle of a period must not take effect
// until the next period.
module pwm_repro_tb;
    localparam integer PERIOD = 8;

    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd2;
    wire       pwm;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer cyc, k, prev, found;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;

        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (3*PERIOD) @(negedge clk);

        // Find the start of a period (rising edge of pwm, duty = 2).
        prev = pwm;
        found = 0;
        for (cyc = 0; (cyc < 4*PERIOD) && (found == 0); cyc = cyc + 1) begin
            @(negedge clk);
            if (prev == 0 && pwm == 1'b1) found = 1;
            prev = pwm;
        end

        if (found == 0) begin
            failed = failed + 1;
            $display("FAIL duty_update: no period start (rising edge) found");
        end else begin
            // Three cycles into the period the duty-2 pulse is over; change duty mid-period.
            repeat (3) @(negedge clk);
            duty = 4'd6;
            // Within the current period the output must stay low.
            for (k = 4; k < 7; k = k + 1) begin
                @(negedge clk);
                if (pwm == 1'b0) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    $display("FAIL duty_update: pwm high %0d cycles into the period after a mid-period duty change (2 -> 6); change must wait for the next period",
                             k);
                end
            end
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
